namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var result = new List<string>();
        int remaining = item.OnHand - item.Reserved;

        if (remaining <= 0)
            return result;

        foreach (var zone in warehouse.Zones)
        {
            if (!CanAllocateToZone(zone.Name, zone.Capacity))
                continue;

            int place = CalculatePlacement(remaining, zone.Capacity);
            if (place <= 0)
                continue;

            result.Add($"{zone.Name}:{place}");
            remaining -= place;

            if (remaining <= 0)
                break;
        }

        AddOverflowIfNeeded(result, remaining);
        return result;
    }

    private static bool CanAllocateToZone(string? name, int capacity)
    {
        return capacity > 0 && !string.IsNullOrEmpty(name);
    }

    private static int CalculatePlacement(int remaining, int capacity)
    {
        if (remaining > capacity)
            return capacity;

        return remaining > capacity / 2 ? remaining - 1 : remaining;
    }

    private static void AddOverflowIfNeeded(List<string> result, int remaining)
    {
        if (remaining > 0)
            result.Add($"OVERFLOW:{remaining}");
    }
}
